-- Semantic world-link data generated by the offline ROM importer.
package.path = "decompilation/gameplay/scripts/?.lua;" ..
    "decompilation/gameplay/scripts/?/init.lua;" .. package.path

local W = require("world_links")
local D = W.data()

local pass, total = 0, 0
local function check(cond, label)
    total = total + 1
    if cond then pass = pass + 1 else print("FAIL " .. label) end
end

-- Each imported link is already expressed as bounds and a semantic transition.
local directions = { north = true, east = true, south = true, west = true }
local links, routed = 0, 0
for scene_id = 0, 55 do
    local scene = D.scenes[scene_id]
    check(scene ~= nil, "scene " .. scene_id .. " present")
    check(scene.event_destinations == nil,
          "ROM selector tables stay out of Lua data " .. scene_id)
    for _, link in ipairs(W.links_in_scene(scene_id)) do
        links = links + 1
        local bounds = link.bounds
        check(directions[link.return_side] == true, "named return side")
        check(bounds.left <= bounds.right and bounds.top <= bounds.bottom,
              "ordered world bounds")
        check(link.transition ~= nil and
              W.transition_at(scene_id, bounds.left, bounds.top) ~= nil,
              "doorway resolves directly to a gameplay transition")
        if link.transition.kind == "scene_change" then
            routed = routed + 1
            check(W.scene_mode(link.transition.destination_scene_id) ~= nil and
                  D.scenes[link.transition.destination_scene_id] ~= nil,
                  "destination has a scene profile")
        else
            check(link.transition.kind == "same_map_service" or
                  link.transition.kind == "contextual_transition" or
                  link.transition.kind == "unresolved_destination",
                  "non-scene doorway transition has a named kind")
        end
    end
end
check(links == 892, "892 imported doorway links, got " .. links)
check(routed > 0, "some doors route")
check(W.transition_at(2, 7424, 2304).destination_scene_id == 13,
      "Redmond doorway routes to the Jump House")
check(W.transition_at(0, 8448, 1792).destination_scene_id == 10,
      "Downtown doorway routes to the destination scene")
-- ROM 0x167AE treats 0x0D as a field-scene result; the importer exposes that
-- field mode as `street` (scene profile 0x1B3C06), not as a resource scene.
check(W.scene_mode(0x0D) == "street" and
      W.scene_mode(0x2D) == "cave" and W.scene_mode(64) == nil,
      "scene profiles carry semantic location modes")

-- Door return formations are keyed by compass side and use map positions.
check(D.return_offsets.south[1].y == 0x140 and
      D.return_offsets.north[1].y == -0x140, "north/south formations")
check(D.return_offsets.east[1].x == 0x1E0 and
      D.return_offsets.west[1].x == -0x1E0, "east/west formations")
local function contact(x, y, side)
    return W.door_contact{
        outdoor_field = true,
        lead = { x = x, y = y },
        camera = { x = 1, y = 2 },
        return_side = side,
    }
end
local cases = {
    { "motel run5", 15584, 10890,
      { { 15584, 11210 }, { 15904, 11210 }, { 15264, 11210 } } },
    { "Little Chiba", 28424, 9350,
      { { 28424, 9670 }, { 28744, 9670 }, { 28104, 9670 } } },
    { "Jump House", 7344, 2680,
      { { 7344, 3000 }, { 7664, 3000 }, { 7024, 3000 } } },
}
for _, c in ipairs(cases) do
    local result = contact(c[2], c[3], "south")
    check(result.saved, c[1] .. " return point saved")
    for runner = 1, 3 do
        check(result.party[runner].x == c[4][runner][1] and
              result.party[runner].y == c[4][runner][2],
              c[1] .. " party member " .. runner)
    end
    check(result.camera.x == 1 and result.camera.y == 2,
          c[1] .. " camera position")
end
local interior = W.door_contact{
    outdoor_field = false,
    lead = { x = 1, y = 1 },
    camera = { x = 0, y = 0 },
    return_side = "north",
}
check(not interior.saved and interior.party == nil,
      "interior contact keeps the previous return point")
check(not pcall(W.door_contact, {
    outdoor_field = true, lead = { x = 0, y = 0 },
    camera = { x = 0, y = 0 }, return_side = "diagonal",
}), "unknown return side rejected")

-- Return facing policies use compass names and bearings in degrees.
local point = contact(15584, 10890, "south")
check(W.return_placement(point, "same_map_service", "north").facing ==
      "south", "same-map service faces south")
check(W.return_placement(point, "building_interior", "west").facing ==
      "west", "building exit preserves its current facing")
check(not pcall(W.return_placement, point, "unknown", 0),
      "unknown return path rejected")
for _, bearing in ipairs({ 0, 90, 180, 270, 45, 315 }) do
    check(W.exit_bearing({
        facing_policy = "face_away_from_entry",
        entry_bearing_degrees = bearing,
    }).bearing_degrees == (bearing + 180) % 360,
       "face away from " .. bearing .. " degrees")
    check(W.exit_bearing({
        facing_policy = "preserve_entry",
        entry_bearing_degrees = bearing,
    }).bearing_degrees == bearing,
       "preserve " .. bearing .. " degrees")
end
check(not pcall(W.exit_bearing, {
    facing_policy = "unknown", entry_bearing_degrees = 0,
}), "unknown facing policy rejected")

-- Service transitions are attached to the actual doorway geometry.
check(W.service_at(2, 28416, 8960).kind == "hospital",
      "Little Chiba hospital")
check(W.service_at(2, 15616, 10496).kind == "hotel",
      "Stoker motel hotel")
check(W.service_at(2, 19712, 8960).kind == "shop",
      "Ares shop")
check(W.service_at(2, 7424, 2304) == nil,
      "Jump House is not a same-map service")

-- The importer resolves cave graph indices into named exits and positions.
check(W.entry_room(6) == 0 and W.entry_room(9) == 3 and
      W.entry_room(2) == nil, "optional entry rooms")
check(D.cave_rooms[W.entry_room(9)].scene == 9 and
      D.cave_rooms[W.entry_room(6)].scene == 6,
      "entry rooms match their destination scenes")
local function cave_exit(room, direction)
    return W.cave_exit({ room = room, direction = direction })
end
local first_exit = cave_exit(0, "north")
check(first_exit.room == 5 and first_exit.scene == 0x2D and
      first_exit.arrival.x == 0x5E00 and first_exit.arrival.y == 0x2280,
      "room 0 north resolves to room 5 and its arrival position")
check(cave_exit(0, "west").room == 0 and
      cave_exit(25, "north") == nil,
      "named exits preserve self-links and reject missing rooms")
local edges = {
    {0,5},{0,6},{0,7},{1,7},{1,11},{2,4},{2,5},{2,9},{2,10},{3,13},
    {3,15},{3,16},{4,5},{7,8},{10,11},{11,12},{12,13},{14,15},{16,17},
    {16,18},{18,21},{19,20},{20,21},{21,23},{22,23},
}
local function linked(from, to)
    for _, direction in ipairs({ "north", "east", "south", "west" }) do
        local exit = cave_exit(from, direction)
        if exit and exit.room == to then return true end
    end
    return false
end
for _, edge in ipairs(edges) do
    check(linked(edge[1], edge[2]) and linked(edge[2], edge[1]),
          "cave connection " .. edge[1] .. "-" .. edge[2])
end
local seen, queue = { [0] = true }, { 0 }
while #queue > 0 do
    local room = table.remove(queue)
    for _, edge in ipairs(edges) do
        for index = 1, 2 do
            local from, to = edge[index], edge[3 - index]
            if from == room and not seen[to] then
                seen[to] = true
                queue[#queue + 1] = to
            end
        end
    end
end
local reached = 0
for _ in pairs(seen) do reached = reached + 1 end
check(reached == 24, "all 24 cave rooms are connected")

print(string.format("world_links: %d/%d", pass, total))
os.exit(pass == total and 0 or 1)
